    p = prices[-window:]
    a = 2 / (window + 1)
    w = np.power(1-a, np.arange(window-1, -1, -1))
    ema = p[0] * w[0] + a * np.sum(p[1:] * w[1:])
    return p[-1] / (ema + 1e-8)

